import json,sys,unittest
from pathlib import Path
stage=Path(sys.argv[1]).resolve()
sys.path[:0]=[str(stage)]
names=['gamelab.tests.test_qa_firearms_magazine_navigation','gamelab.tests.test_qa_firearms_magazine_fixture']
suite=unittest.defaultTestLoader.loadTestsFromNames(names)
def ids(items):
    for item in items:
        if isinstance(item,unittest.TestSuite):
            yield from ids(item)
        else:
            yield item.id()
selected=list(ids(suite))
if len(selected)!=38 or len(set(selected))!=38:
    raise SystemExit('Expected38 unique actual-Python controls')
result=unittest.TextTestRunner(verbosity=2).run(suite)
source_names=names+['gamelab.bots.qa_firearms_magazine_navigation','gamelab.bots.qa_firearms_magazine_fixture','gamelab.bots.qa_specs_navigation','gamelab.bots.qa_firearms_input_geometry']
origins={name:str(Path(sys.modules[name].__file__).resolve()) for name in source_names}
if any(not Path(path).is_relative_to(stage) for path in origins.values()):
    raise SystemExit('Expected stage-local test/helper origins')
if any(name in sys.modules for name in ['gamelab.bots.qa_input_target','gamelab.session','gamelab.runner','gamelab.winproc']):
    raise SystemExit('Unexpected native hierarchy/collector import')
print('E013_ORIGINS '+json.dumps(origins,sort_keys=True),flush=True)
print('E013_RESULT '+json.dumps({'testsRun':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'skips':len(result.skipped),'expectedFailures':len(result.expectedFailures),'unexpectedSuccesses':len(result.unexpectedSuccesses)},sort_keys=True),flush=True)
raise SystemExit(0 if result.wasSuccessful() and result.testsRun==38 and not result.skipped and not result.expectedFailures and not result.unexpectedSuccesses else 1)

